#include <stdio.h>
#include <stdlib.h>

int main(void)
{
    int *a = malloc(3 * sizeof *a);
    if (a == NULL) { return 1; }
    a[0] = 2; a[1] = 4; a[2] = 6;
    printf("%d\n", a[0] + a[1] + a[2]);
    free(a);
    a = NULL;
    return 0;
}

#include <stdio.h>

void fill(int *a)
{
    a[0] = 7;
    a[1] = 9;
}

int main(void)
{
    int a[2] = {0};
    fill(a);
    printf("%d %d\n", a[0], a[1]);
    return 0;
}

